// The reading of an answer of the check: a topic, and the claims about files that the topic makes.
// The answer is one JSON object, so the check reads the claims and not a keyword such as `NONE`.
// This file has no `node:` import and no use of `Bun`, because Claude Code runs it in the mod runtime.

import { MAX_CLAIMS, MAX_ID_CHARS, MAX_TOPIC_CHARS } from "../limits.ts";
import { clip } from "./prompt.ts";

/** What the topic says about a file: it is not there, it has no bytes, or it ends in the middle. */
export type ClaimState = "missing" | "empty" | "cut";

/** A claim of the topic about one file. */
export type Claim = { path: string; state: ClaimState };

/** A topic with the claims that the disk must back. */
export type Topic = { topic: string; id: string; claims: Claim[] };

/** The reading of an answer: a topic, `none` when the model has no topic, or `malformed` when the answer is not the object that the prompt asks for. */
export type Reading = Topic | "none" | "malformed";

/** The shape of a topic id: words of lowercase ASCII, joined with `-`. */
const ID_SHAPE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

const STATES: readonly string[] = ["missing", "empty", "cut"];

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

/** One claim, or `undefined` when the entry has no path or an unknown state. */
const claimOf = (entry: unknown): Claim | undefined => {
  if (!isRecord(entry)) return undefined;
  const { path, state } = entry;
  if (typeof path !== "string" || path.length === 0) return undefined;
  if (typeof state !== "string" || !STATES.includes(state)) return undefined;
  return { path, state: state as ClaimState };
};

/** The claims of a parsed answer, or `undefined` when one entry is wrong or there are more than `MAX_CLAIMS`. */
const claimsOf = (raw: unknown): Claim[] | undefined => {
  if (raw === undefined) return [];
  if (!Array.isArray(raw) || raw.length > MAX_CLAIMS) return undefined;
  const claims = raw.map(claimOf);
  return claims.every((c) => c !== undefined) ? (claims as Claim[]) : undefined;
};

/** The object between the first `{` and the last `}` of `answer`, or `undefined`. */
const objectOf = (answer: string): Record<string, unknown> | undefined => {
  const from = answer.indexOf("{");
  const to = answer.lastIndexOf("}");
  if (from < 0 || to < from) return undefined;
  try {
    const parsed: unknown = JSON.parse(answer.slice(from, to + 1));
    return isRecord(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
};

/** Reads an answer of the check. A `topic` of `null` or of blank text is `none`. */
export const readingOf = (answer: string): Reading => {
  const parsed = objectOf(answer);
  if (parsed === undefined || !("topic" in parsed)) return "malformed";
  const { topic } = parsed;
  if (topic === null) return "none";
  if (typeof topic !== "string") return "malformed";
  const claims = claimsOf(parsed["claims"]);
  if (claims === undefined) return "malformed";
  const text = topic.replace(/\s+/g, " ").trim();
  if (text.length === 0) return "none";
  const id = parsed["id"];
  if (typeof id !== "string" || !ID_SHAPE.test(id) || id.length > MAX_ID_CHARS)
    return "malformed";
  return { topic: clip(text, MAX_TOPIC_CHARS), id, claims };
};

/** True when `text` ends in the middle: it has bytes, and the last byte is not a line end. */
export const isCutShort = (text: string): boolean =>
  text.length > 0 && !text.endsWith("\n");

/** The state file of Claude Code, which holds the cached values of the account. */
export const STATE_FILE = ".claude.json";

/** True when `file`, the text of the state file `STATE_FILE` of Claude Code, holds the value `true` for `tengu_jolly_dewdrop`. */
export const isFlagOn = (file: string | undefined): boolean => {
  if (file === undefined) return false;
  try {
    const state: unknown = JSON.parse(file);
    const features = isRecord(state) ? state["cachedGrowthBookFeatures"] : null;
    return isRecord(features) && features["tengu_jolly_dewdrop"] === true;
  } catch {
    return false;
  }
};
